// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.conversationimport timber.log.Timberimport com.roshan.persona.voice.capture.AudioCapturePipelineimport com.roshan.persona.voice.tts.Emotionimport com.roshan.persona.voice.tts.EmotionalTtsEngineimport com.roshan.persona.voice.tts.VoicePersonaimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.CoroutineScopeimport kotlinx.coroutines.Jobimport kotlinx.coroutines.delayimport kotlinx.coroutines.flow.Flowimport kotlinx.coroutines.flow.MutableSharedFlowimport kotlinx.coroutines.flow.MutableStateFlowimport kotlinx.coroutines.flow.StateFlowimport kotlinx.coroutines.flow.asSharedFlowimport kotlinx.coroutines.flow.asStateFlowimport kotlinx.coroutines.isActiveimport kotlinx.coroutines.launchimport kotlinx.coroutines.yieldimport java.util.concurrent.atomic.AtomicBooleanimport java.util.concurrent.atomic.AtomicReference/** * NOUS — Conversation Engine (§12 Natural Turn-Taking). * * Coordinates the natural flow of conversation: who speaks when, when NOUS * should start processing (early, via end-of-speech prediction), and what * NOUS says while thinking (filler sounds). * * ## Responsibilities * * 1. **Turn-taking** — track whose turn it is (user / NOUS / idle). * 2. **End-of-speech prediction** — call [EndOfSpeechPredictor] on every *    audio chunk; when it predicts end-of-turn, notify the Brain early *    (so the response is ready by the time the user stops). * 3. **Filler sounds** — when the Brain is taking >X ms to respond, play *    a filler ("Hmm.", "Let me think.") so the user knows NOUS is working. * 4. **Silence detection** — if VAP/heuristic predicts end-of-turn AND *    500 ms of silence has elapsed, commit the turn (hand off to Brain). * * ## State machine * * ``` * IDLE ──(wake word)──→ LISTENING ──(end-of-speech predicted)──→ PROCESSING *   ↑                      │                                         │ *   │                      │                                     (filler if >500ms) *   │                      │                                         │ *   └──(TTS done)────────SPEAKING ←──(brain response)────────────────┘ * ``` * * ## Latency budget (§15 + §17) * *  - End-of-speech prediction: < 10 ms per chunk (heuristic) or < 50 ms (VAP) *  - Brain processing starts:  ~100 ms before user stops (VAP prediction) *  - Filler sound:             < 200 ms after brain starts processing *  - TTS first sound:          < 200 ms after brain produces text * * Net perceived latency: < 100 ms (vs 500+ ms for naive "wait for silence" * implementations). * * ## Testability * * The engine depends on [EndOfSpeechPredictor] (already testable), an * audio stream (Flow — tests inject a fake), and a [FillerPlayer] callback * (tests inject a fake). The state machine is the only non-trivial logic * and is fully verifiable via the [state] StateFlow. * * @see <a href="docs/strategy/module-5-strategy-v2.md">§12 Conversation Engine — Natural Turn-Taking</a> */class ConversationEngine(    private val predictor: EndOfSpeechPredictor,    private val fillerPlayer: FillerPlayer,    private val engineDispatcher: CoroutineDispatcher,    private val config: Config = Config(),) {    /**     * Configuration for the conversation engine.     *     * @param fillerDelayMs       how long to wait before playing a filler     *                            (default 500 ms — gives Brain a chance to     *                            respond instantly if it can).     * @param commitSilenceMs     silence required after end-of-speech     *                            prediction before committing the turn     *                            (default 300 ms — confirms the prediction).     * @param fillerCooldownMs    minimum gap between consecutive fillers     *                            (default 3 s — avoids filler spam).     */    data class Config(        val fillerDelayMs: Long = DEFAULT_FILLER_DELAY_MS,        val commitSilenceMs: Long = DEFAULT_COMMIT_SILENCE_MS,        val fillerCooldownMs: Long = DEFAULT_FILLER_COOLDOWN_MS,    ) {        init {            require(fillerDelayMs >= 0) { "fillerDelayMs must be non-negative" }            require(commitSilenceMs >= 0) { "commitSilenceMs must be non-negative" }            require(fillerCooldownMs >= 0) { "fillerCooldownMs must be non-negative" }        }        companion object {            const val DEFAULT_FILLER_DELAY_MS = 500L            const val DEFAULT_COMMIT_SILENCE_MS = 300L            const val DEFAULT_FILLER_COOLDOWN_MS = 3_000L        }    }    private val _state = MutableStateFlow(ConversationState.IDLE)    /** Current conversation state — observe via [state]. */    val state: StateFlow<ConversationState> = _state.asStateFlow()    private val _events = MutableSharedFlow<ConversationEvent>(        extraBufferCapacity = 32,        onBufferOverflow = kotlinx.coroutines.channels.BufferOverflow.DROP_OLDEST,    )    /** Hot stream of conversation events (turn committed, filler played, etc.). */    val events: Flow<ConversationEvent> = _events.asSharedFlow()    private val monitorJob = AtomicReference<Job?>(null)    private val lastFillerMs = AtomicReference(0L)    private val lastChunkHadVoice = AtomicBoolean(false)    private var silenceStartMs = 0L    private var endOfSpeechPredicted = false    /**     * Begin monitoring an audio stream for end-of-speech.     *     * The engine transitions to [ConversationState.LISTENING] and starts     * running [EndOfSpeechPredictor] on every chunk. When end-of-speech is     * predicted AND confirmed by silence, it emits a     * [ConversationEvent.TurnCommitted] event (the Brain listens for this     * to start processing).     *     * @param audioStream live audio chunks from [AudioCapturePipeline.chunks].     * @param scope       coroutine scope.     */    fun startListening(audioStream: Flow<AudioCapturePipeline.AudioChunk>, scope: CoroutineScope) {        if (_state.value != ConversationState.IDLE) {            Timber.tag(TAG).w("startListening called in state ${_state.value} — ignoring.")            return        }        _state.value = ConversationState.LISTENING        endOfSpeechPredicted = false        silenceStartMs = 0L        lastChunkHadVoice.set(true)  // assume voice until proven otherwise        monitorJob.set(scope.launch(engineDispatcher) {            try {                audioStream.collect { chunk ->                    if (!isActive) return@collect                    processChunk(chunk)                }            } catch (t: Throwable) {                Timber.tag(TAG).e("Conversation monitor crashed", t)            } finally {                if (_state.value == ConversationState.LISTENING) {                    _state.value = ConversationState.IDLE                }            }        })    }    /** Stop listening and return to IDLE. */    fun stopListening() {        monitorJob.getAndSet(null)?.cancel()        _state.value = ConversationState.IDLE        endOfSpeechPredicted = false        silenceStartMs = 0L    }    /**     * Notify the engine that the Brain has started processing.     *     * Transitions to [ConversationState.PROCESSING]. After [Config.fillerDelayMs],     * if the Brain hasn't produced a response yet, a filler is played.     */    fun onBrainProcessingStarted(scope: CoroutineScope) {        if (_state.value != ConversationState.LISTENING) return        _state.value = ConversationState.PROCESSING        // Schedule a filler after the delay.        scope.launch(engineDispatcher) {            delay(config.fillerDelayMs)            if (_state.value == ConversationState.PROCESSING) {                playFillerIfNeeded(BrainProcessingState.SEARCHING_MEMORY)            }        }    }    /**     * Notify the engine that the Brain has produced a response and TTS has started.     *     * Transitions to [ConversationState.SPEAKING]. When TTS completes, the     * engine returns to IDLE.     */    fun onTtsStarted() {        _state.value = ConversationState.SPEAKING    }    /** Notify the engine that TTS has finished — return to IDLE. */    fun onTtsDone() {        _state.value = ConversationState.IDLE    }    // ──────────────────────────────────────────────────────────────────────    internal suspend fun processChunk(chunk: AudioCapturePipeline.AudioChunk) {        // Track silence.        if (chunk.hasVoice) {            silenceStartMs = 0L            lastChunkHadVoice.set(true)        } else if (lastChunkHadVoice.get()) {            silenceStartMs = chunk.timestampMs            lastChunkHadVoice.set(false)        }        val silenceMs = if (silenceStartMs == 0L) 0L else chunk.timestampMs - silenceStartMs        // Build audio features (silence-only for now — intonation/rate would        // require a feature extractor; will be wired in Step 5.14).        val features = AudioFeatures(            intonationDropScore = 0f,            rateSlowdownScore = 0f,            hasFillerWord = false,            silenceMs = silenceMs,        )        // Predict end-of-speech.        val prediction = predictor.predictEndOfSpeech(chunk.samples, features)        if (prediction.willEndWithin1Second && !endOfSpeechPredicted) {            endOfSpeechPredicted = true            _events.emit(ConversationEvent.EndOfSpeechPredicted(prediction))        }        // Commit the turn when end-of-speech is predicted AND silence is confirmed.        if (endOfSpeechPredicted && silenceMs >= config.commitSilenceMs) {            _events.emit(ConversationEvent.TurnCommitted(                triggerAudio = chunk.samples,                timestampMs = chunk.timestampMs,            ))            stopListening()            return        }        // Hard fallback: if silence exceeds the STT timeout (500 ms) without        // a prediction, commit anyway (the user really did stop).        if (silenceMs >= predictor.config.silenceMsForEnd && !endOfSpeechPredicted) {            _events.emit(ConversationEvent.TurnCommitted(                triggerAudio = chunk.samples,                timestampMs = chunk.timestampMs,            ))            stopListening()        }    }    /** Play a filler if cooldown has elapsed. */    private suspend fun playFillerIfNeeded(state: BrainProcessingState) {        val now = System.currentTimeMillis()        val last = lastFillerMs.get()        if (now - last < config.fillerCooldownMs) return        lastFillerMs.set(now)        val filler = FillerSounds.getFiller(state)        fillerPlayer.playFiller(filler)        _events.emit(ConversationEvent.FillerPlayed(filler))    }    private companion object {        private const val TAG = "ConversationEngine"    }}// ──────────────────────────────────────────────────────────────────────────/** Conversation state machine. */enum class ConversationState {    /** No active conversation — wake word listener is in charge. */    IDLE,    /** User is speaking — engine is monitoring for end-of-speech. */    LISTENING,    /** User has finished; Brain is processing the utterance. */    PROCESSING,    /** NOUS is speaking via TTS. */    SPEAKING,}// ──────────────────────────────────────────────────────────────────────────/** Events emitted by the conversation engine. */sealed interface ConversationEvent {    /** End-of-speech was predicted (Brain can start processing early). */    data class EndOfSpeechPredicted(val prediction: EndOfSpeechPrediction) : ConversationEvent    /** The user's turn has been committed — Brain must process now. */    data class TurnCommitted(        val triggerAudio: ShortArray,        val timestampMs: Long,    ) : ConversationEvent {        override fun equals(other: Any?): Boolean {            if (this === other) return true            if (other !is TurnCommitted) return false            return timestampMs == other.timestampMs &&                triggerAudio.contentEquals(other.triggerAudio)        }        override fun hashCode(): Int {            var result = triggerAudio.contentHashCode()            result = 31 * result + timestampMs.hashCode()            return result        }    }    /** A filler sound was played. */    data class FillerPlayed(val filler: String) : ConversationEvent}// ──────────────────────────────────────────────────────────────────────────/** What the Brain is doing — drives filler selection. */enum class BrainProcessingState {    SEARCHING_MEMORY,    CLOUD_LLM,    AGENTIC_EXECUTING,    OTHER,}// ──────────────────────────────────────────────────────────────────────────/** * Filler sound library (§12 Filler Sounds). * * When the Brain takes >X ms to respond, NOUS fills the silence with a * short phrase so the user knows it's working. The phrase is selected * based on what the Brain is doing (searching memory, calling cloud LLM, * executing an agent). * * Phrases are deliberately short (< 1 s TTS) so they don't delay the * actual response. */object FillerSounds {    val THINKING = listOf("Hmm.", "Let me think.", "One moment.", "Give me a second.")    val SEARCHING = listOf("Let me check.", "Looking that up.", "Searching now.")    val PROCESSING = listOf("Processing.", "Working on it.", "Almost there.")    /** Last-used index per category — avoids repeating the same filler twice in a row. */    private val lastIndices = mutableMapOf<BrainProcessingState, Int>()    /**     * Get a filler phrase for the given brain state.     *     * Cycles through the list (deterministic) rather than random — sounds     * more intentional and is testable.     */    @Synchronized    fun getFiller(state: BrainProcessingState): String {        val list = when (state) {            BrainProcessingState.SEARCHING_MEMORY -> THINKING            BrainProcessingState.CLOUD_LLM -> SEARCHING            BrainProcessingState.AGENTIC_EXECUTING -> PROCESSING            BrainProcessingState.OTHER -> THINKING        }        val lastIdx = lastIndices[state] ?: -1        val nextIdx = (lastIdx + 1) % list.size        lastIndices[state] = nextIdx        return list[nextIdx]    }    /** Reset the cycling state (for tests). */    @Synchronized    fun reset() {        lastIndices.clear()    }}// ──────────────────────────────────────────────────────────────────────────/** * Callback for playing filler sounds. * * Real implementation calls [EmotionalTtsEngine.speak] with [Emotion.THoughtful] * and the active [VoicePersona]. Tests inject a fake to verify filler * selection without needing the TTS engine. */fun interface FillerPlayer {    /** Play the given filler text. */    suspend fun playFiller(text: String)}
